import {beforeEach,test,expect} from "bun:test";
import {goalDefinition,goalResult,goalReadProblem,goalActionProblem,goalGuidance,goalValueReviewProblem,valueReviewChecks,effectiveGoal,goalQuadrantBucket,visibleGoals,goalManagers} from "../src/goals";
import {planEligibleGoals} from "../src/plans";
import {visibleActivityEvents} from "../src/knowledge";
const storage=new Map();Object.defineProperty(globalThis,"localStorage",{configurable:true,writable:true,value:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v),removeItem:k=>storage.delete(k)}});
const api=await import("../src/store.js?okr-collaboration");
beforeEach(api.reset);
const get=id=>api.read().resources.goals.find(g=>g.id===id);
const input=(patch={})=>({collaborationVersion:1,tenantId:"studio",goalType:"ORGANIZATION",timeMode:"NATURAL",stageName:"",reviewerId:"H-lin",visibility:"SCOPE",collaborators:[{id:"atlas",kind:"Agent",permissions:["suggest","draft","checkin"]}],beneficiaries:"服务使用者",value:"减少错误决策",resources:"已明确负责人及观察时间",name:"改进可核对结果",subjectKey:"tenant:studio",ownerId:"H-lin",ownerKind:"Human",owner:"林予",periodKind:"YEAR",periodStart:"2026-01-01",periodEnd:"2026-12-31",timezone:"UTC",alignments:[],riskPolicy:{},krs:[{id:"KR-1",title:"降低失误率",unit:"%",baseline:20,target:5,direction:"DECREASE",weight:1,source:"MANUAL",metric:"",evidenceRequired:false}],...patch});
const create=patch=>api.saveStructuredGoal(input(patch));
const review=(id,patch={})=>api.recordGoalValueReview(id,{revision:get(id).revision,agentId:"atlas",simulated:true,guidanceRevision:goalGuidance(api.read()).revision,checks:Object.fromEntries(Object.keys(valueReviewChecks).map(k=>[k,{result:"PASS",basis:`已核对${k}的上下文与证据，仅本地模拟`}])),...patch});
const decide=(id,status)=>api.resourceCommand("goals",id,status,"Human 核对固定承诺","",{revision:get(id).revision,status:get(id).status});
const publish=id=>{review(id);decide(id,"待审核");decide(id,"进行中");};
const atomic=fn=>{const before=structuredClone(api.read());expect(fn).toThrow();expect(api.read()).toEqual(before);};
function phase(parent,patch={}){return create({goalType:"PROJECT_STAGE",subjectKey:"project:launch",stageName:"研究阶段",timeMode:"STAGE",periodKind:"MONTH",periodStart:"2026-02-03",periodEnd:"2026-05-17",alignments:[{targetGoalId:parent,targetKrId:"KR-1",relation:"breakdown",reason:"明确贡献"}],...patch});}

test("multiple project phases use independent dates and retain natural periods separately",()=>{const p=create();publish(p);const a=phase(p),b=phase(p,{name:"并行阶段",stageName:"验证",periodStart:"2026-04-11",periodEnd:"2026-10-21"});expect(get(a).periodStart).toBe("2026-02-03");expect(get(b).periodKind).toBe("MONTH");expect(get(a).goalType).toBe("PROJECT_STAGE");expect(get(a).ownerKind).toBe("Human");atomic(()=>phase(p,{periodEnd:"2026-02-01"}));atomic(()=>phase(p,{goalType:"HUMAN"}));expect(api.read().resources.goals.filter(g=>g.subjectKey==="project:launch")).toHaveLength(2);});
test("unrun unknown failed and obsolete value review never approves; six criteria are fixed",()=>{const id=create();atomic(()=>decide(id,"待审核"));review(id,{checks:Object.fromEntries(Object.keys(valueReviewChecks).map(k=>[k,{result:k==="reuse"?"UNKNOWN":"PASS",basis:"核对依据"}]))});atomic(()=>decide(id,"待审核"));review(id);const fixed=structuredClone(get(id).valueReview);decide(id,"待审核");api.saveGoalGuidance({...goalGuidance(api.read()),reason:"增加核验说明",keyResult:"新的 KR 证据约定"});atomic(()=>decide(id,"进行中"));expect(get(id).valueReview).toEqual(fixed);expect(goalValueReviewProblem(api.read(),get(id))).not.toBe("");expect(api.read().goalGuidance.history[0].revision).toBe(1);});
test("simulated review must be explicitly authorized and cannot pretend a real model ran",()=>{const id=create();atomic(()=>review(id,{simulated:false}));atomic(()=>review(id,{agentId:"muse"}));review(id);expect(get(id).valueReview).toMatchObject({source:"LOCAL_SIMULATION",recordedBy:"H-lin",agentId:"atlas",guidanceRevision:1});expect(get(id).valueReview.definition).toEqual(goalDefinition(get(id)));api.update(s=>s.agents.find(a=>a.id==="atlas").status="退役");atomic(()=>decide(id,"待审核"));});
test("approved baseline survives proposed adjustment and stale decisions; new Human decision replaces it",()=>{const id=create();publish(id);const before=structuredClone(get(id).activeBaseline);atomic(()=>api.saveStructuredGoal({...get(id),name:"变更",changeReason:"临时任务"}));api.saveStructuredGoal({...get(id),name:"变更",changeReason:"临时任务",changeImpact:"减少本期承诺范围"});expect(get(id).status).toBe("草稿");expect(get(id).activeBaseline).toEqual(before);expect(effectiveGoal(get(id)).name).toBe(before.definition.name);expect(get(id).changeProposal).toMatchObject({reason:"临时任务",impact:"减少本期承诺范围",status:"草稿"});expect(get(id).valueReview).toBeNull();expect(get(id).valueReviewHistory).toHaveLength(1);atomic(()=>decide(id,"待审核"));publish(id);expect(get(id).activeBaseline.definition.name).toBe("变更");expect(get(id).changeProposal.status).toBe("已批准");expect(get(id).history.some(h=>h.before?.activeBaseline?.definition.name===before.definition.name)).toBe(true);});
test("qualitative KR freezes delivery use criteria and evidence, unknown never becomes success",()=>{const id=create({krs:[{id:"Q1",kind:"QUALITATIVE",title:"让一线采用研究结果",delivery:"研究结论与决策备忘",use:"支持上线取舍",criteria:"决策人逐条核对并说明采用理由",evidencePlan:"固定成果及采用记录",dueDate:"2026-12-15",weight:1}]});publish(id);const base={revision:get(id).revision,observedAt:new Date(Date.now()-1000).toISOString(),reason:"逐条核对",delivery:"已交付备忘",use:"决策采用记录",judgment:"MET",evidence:[]};atomic(()=>api.recordGoalObservation(id,"Q1",base));api.recordGoalObservation(id,"Q1",{...base,judgment:"UNKNOWN",evidence:[{kind:"URL",ref:"https://example.com/review"}]});expect(goalResult(get(id)).progress).toBeNull();api.recordGoalObservation(id,"Q1",{...base,revision:get(id).revision,evidence:[{kind:"work",id:"W-104",version:3}]});expect(goalResult(get(id)).progress).toBe(1);const o=get(id).krs[0].observations.at(-1);expect(o.criteria).toBe(get(id).krs[0].criteria);api.update(s=>s.work.find(w=>w.id==="W-104").title="后续名称");expect(o.evidence[0].snapshot.title).not.toBe("后续名称");expect(api.read().work.find(w=>w.id==="W-104").accepted).toBe(false);});
test("private Human objectives do not leak to tenant owner, search candidates or activity",()=>{const id=create({goalType:"HUMAN",subjectKey:"human:H-zhou",ownerId:"H-zhou",ownerKind:"Human",reviewerId:"H-lin",visibility:"PRIVATE"});expect(goalReadProblem(api.read(),get(id))).toBe("");api.update(s=>{const g=s.resources.goals.find(g=>g.id===id);g.reviewerId="H-zhou";g.collaborators=[];s.events.push({id:"private-goal-event",target:`/goals/${id}`,text:g.name});});expect(goalReadProblem(api.read(),get(id))).not.toBe("");expect(visibleGoals(api.read()).some(g=>g.id===id)).toBe(false);expect(visibleActivityEvents(api.read()).some(e=>e.id==="private-goal-event")).toBe(false);atomic(()=>api.saveStructuredGoal({...get(id),changeReason:"不能接管"}));});
test("organization superior does not grant cross-project access or Agent task assignment authority",()=>{const p=create();publish(p);const id=phase(p);api.update(s=>{s.role="executor";s.projects.find(p=>p.id==="launch").owner="周宁";s.organization.projectRoles=s.organization.projectRoles.filter(r=>r.memberId!=="H-lin");});expect(goalManagers(api.read(),"H-zhou")).toContain("H-lin");expect(goalReadProblem(api.read(),get(id))).not.toBe("");expect(goalReadProblem(api.read(),get(id),"muse")).not.toBe("");atomic(()=>api.recordGoalDiscussion(id,{revision:get(id).revision,text:"越权"}));});
test("permissions distinguish suggestions drafts checkins approvals; revoked grant and retired Agent stop writes",()=>{const id=create();const state=api.read();expect(goalActionProblem(state,get(id),"approve","atlas")).not.toBe("");api.saveStructuredGoal({...get(id),changeReason:"收窄协作",collaborators:[{id:"atlas",kind:"Agent",permissions:["suggest"]}]});expect(goalActionProblem(api.read(),get(id),"suggest","atlas")).toBe("");expect(goalActionProblem(api.read(),get(id),"draft","atlas")).not.toBe("");atomic(()=>review(id));atomic(()=>api.saveStructuredGoal({...get(id),collaborationVersion:undefined,changeReason:"绕过"}));atomic(()=>api.saveStructuredGoal({...get(id),changeReason:"越权上级",collaborators:[{id:"H-xu",kind:"Human",permissions:["draft"]}]}));});
test("discussion resolution and check-in preserve independent progress confidence risk help and definitions",()=>{const id=create();publish(id);const definition=structuredClone(goalDefinition(get(id))),progress=goalResult(get(id));api.recordGoalDiscussion(id,{revision:get(id).revision,text:"资源不足的分歧",simulateAgentId:"atlas"});const d=get(id).discussions[0];api.recordGoalDiscussion(id,{revision:get(id).revision,action:"resolve",discussionId:d.id,text:"减少并行工作，保留原承诺待正式调整"});expect(get(id).discussions[0].resolution.recordedBy).toBe("H-lin");api.recordGoalCheckin(id,{revision:get(id).revision,progress:"尚无效果观察",confidence:"LOW",risk:"依赖等待",help:"请求负责人协调",simulateAgentId:"atlas"});expect(get(id).checkins[0]).toMatchObject({confidence:"LOW",risk:"依赖等待",help:"请求负责人协调",source:"LOCAL_SIMULATION"});expect(goalDefinition(get(id))).toEqual(definition);expect(goalResult(get(id))).toEqual(progress);atomic(()=>api.recordGoalCheckin(id,{revision:get(id).revision,progress:"100%",confidence:"HIGH",risk:"",help:""}));});
test("custom quadrant has no default priority model; missing positions stay unknown and axis revisions invalidate positions",()=>{const id=create();expect(goalQuadrantBucket(api.read(),get(id))).toBe("unknown");const axis={label:"可观察价值",min:0,split:3,max:5,lowLabel:"证据有限",highLabel:"证据充分"};api.saveGoalQuadrant({revision:0,x:axis,y:{...axis,label:"资源匹配"},reason:"团队约定的评估口径"});api.positionGoalQuadrant(id,{revision:get(id).revision,configRevision:1,x:3,y:1,reason:"核对本期资料"});expect(goalQuadrantBucket(api.read(),get(id))).toBe("high-low");const p=create({goalType:"HUMAN",subjectKey:"human:H-lin",visibility:"PRIVATE"});expect(goalQuadrantBucket(api.read(),get(p))).toBeNull();atomic(()=>api.positionGoalQuadrant(p,{revision:get(p).revision,configRevision:1,x:3,y:1,reason:"不应进入"}));api.saveGoalQuadrant({revision:1,x:axis,y:axis,reason:"新口径"});expect(goalQuadrantBucket(api.read(),get(id))).toBe("unknown");expect(api.read().goalQuadrant.history).toHaveLength(1);});
test("tenant switch isolates guidance quadrant records and rejects captured other-tenant forms",()=>{const id=create();api.saveGoalGuidance({...goalGuidance(api.read()),reason:"本租户指导"});const old=structuredClone(get(id));const tenant=api.createTenant("隔离测试租户");expect(goalGuidance(api.read()).revision).toBe(1);expect(api.read().goalQuadrant).toBeNull();atomic(()=>api.saveStructuredGoal({...old,changeReason:"跨租户"}));api.switchTenant("studio");expect(goalGuidance(api.read()).revision).toBe(2);expect(get(id).id).toBe(id);});
test("plan references use approved definition during pending change, not the draft target",()=>{const id=create();publish(id);api.saveStructuredGoal({...get(id),changeReason:"评估变更",changeImpact:"待批不影响当前承诺",krs:get(id).krs.map(k=>({...k,title:"待批标题",target:3}))});const eligible=planEligibleGoals(api.read(),"human:H-lin").find(g=>g.id===id);expect(eligible.krs[0].title).toBe("降低失误率");expect(eligible.status).toBe("进行中");});
test("authorized Agent can propose its own objective but Human approval remains explicit",()=>{const a=api.read().agents.find(a=>a.id==="atlas");api.update(s=>s.agents.find(a=>a.id==="atlas").owner="林予");const root=create();publish(root);const id=create({goalType:"AGENT",subjectKey:"agent:atlas",ownerId:"atlas",ownerKind:"Agent",owner:a.name,reviewerId:"H-lin",visibility:"PRIVATE",simulateAgentId:"atlas",alignments:[{targetGoalId:root,targetKrId:"KR-1",relation:"breakdown",reason:"明确自身贡献"}]});expect(get(id).draftOrigin).toMatchObject({kind:"Agent",agentId:"atlas",source:"LOCAL_SIMULATION"});expect(goalActionProblem(api.read(),get(id),"approve","atlas")).not.toBe("");publish(id);expect(get(id).approval.actorKind).toBe("Human");});
test("designated project Human can approve as executor but cannot appoint unrelated supervisor",()=>{const root=create();publish(root);const id=phase(root);api.update(s=>s.role="executor");review(id);decide(id,"待审核");decide(id,"进行中");expect(get(id).approval.permission).toBe("explicit-goal-human-reviewer");atomic(()=>api.saveStructuredGoal({...get(id),reviewerId:"H-xu",changeReason:"换负责人",changeImpact:"未知"}));});
test("new collaboration panels expose honest fixed baseline, guidance and unknown quadrant labels",async()=>{const React=await import("react"),{renderToStaticMarkup}=await import("react-dom/server"),{GoalCollaboration,GoalQuadrants}=await import("../src/goal-collaboration.jsx");const id=create();publish(id);api.saveStructuredGoal({...get(id),name:"待批新名称",changeReason:"依赖变化",changeImpact:"推迟窗口"});let html=renderToStaticMarkup(React.createElement(GoalCollaboration,{state:api.read(),goal:get(id)}));for(const text of ["当前生效定义 r1","改进可核对结果","待批新名称","依赖变化","推迟窗口","未运行，不能标为通过","共同讨论与分歧处理","周期 check-in","林予（H-lin）","写作指导"])expect(html).toContain(text);expect(html).not.toContain("[object Object]");html=renderToStaticMarkup(React.createElement(GoalQuadrants,{state:api.read(),rows:[get(id)]}));expect(html).toContain("待配置");expect(html).toContain("未分类");expect(html).toContain("待批新名称");});
test("private goal export cannot bypass canonical read gate",()=>{const id=create({goalType:"HUMAN",subjectKey:"human:H-zhou",ownerId:"H-zhou",ownerKind:"Human",reviewerId:"H-lin",visibility:"PRIVATE"});api.update(s=>{s.resources.goals.find(g=>g.id===id).reviewerId="H-zhou";});expect(()=>api.exportData("goals",get(id))).toThrow("私密");});
test("Human identifiers cannot be relabeled as simulated Agent provenance",()=>{const id=create();publish(id);atomic(()=>api.saveStructuredGoal({...get(id),changeReason:"伪造主体",changeImpact:"不允许",simulateAgentId:"H-lin"}));atomic(()=>api.recordGoalDiscussion(id,{revision:get(id).revision,text:"伪造Agent",simulateAgentId:"H-lin"}));atomic(()=>api.recordGoalCheckin(id,{revision:get(id).revision,progress:"未知",confidence:"UNKNOWN",risk:"无",help:"无",simulateAgentId:"H-lin"}));atomic(()=>create({draftOrigin:{simulated:true,agentId:"muse"}}));});

test("nonpersonal visibility cannot claim private while remaining scope-readable",()=>{
 atomic(()=>create({visibility:"PRIVATE"}));const id=create();publish(id);
 atomic(()=>phase(id,{visibility:"PRIVATE"}));
 const human=create({goalType:"HUMAN",subjectKey:"human:H-lin",visibility:"PRIVATE"});
 expect(get(human).visibility).toBe("PRIVATE");
});

test("legacy scalar conversion preserves original fields in a collaboration change proposal",()=>{
  const original=structuredClone(get("G-01"));
  expect(original.krs).toBeUndefined();
  const id=api.saveStructuredGoal(input({id:original.id,revision:original.revision||1,changeReason:"明确转换旧标量目标，不生成过去观察",krs:[{...input().krs[0],unit:"天",baseline:8,target:5}]}));
  const goal=get(id);
  expect(goal.status).toBe("草稿");
  expect(goal.changeProposal.before.baseline).toBe(original.baseline);
  expect(goal.changeProposal.before.krs).toBeUndefined();
  expect(goal.history.at(-1).before.baseline).toBe(original.baseline);
  expect(goal.krs[0].observations).toEqual([]);
  expect(goal.activeBaseline).toBeNull();
  expect(goal.changeProposal.after.krs[0].baseline).toBe(8);
});
